INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'HEADING', 0, $txt${"text": "Masalah: Karakter Mandarin Terlihat Menakutkan"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'PARAGRAPH', 1, $txt${"text": "Banyak orang ingin belajar bahasa Mandarin tetapi mundur begitu melihat ribuan karakter Hanzi. Padahal, ada pintu masuk yang jauh lebih ramah: pinyin, sistem romanisasi resmi yang mengubah bunyi bahasa Mandarin menjadi huruf Latin. Menguasai pinyin adalah langkah pertama sebelum menyentuh karakter."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'HEADING', 2, $txt${"text": "Penjelasan: Apa Itu Pinyin?"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'PARAGRAPH', 3, $txt${"text": "Pinyin adalah sistem penulisan bunyi bahasa Mandarin menggunakan alfabet Latin, dikembangkan pada tahun 1950-an dan diakui ISO pada 1982. Setiap suku kata Mandarin terdiri dari inisial (konsonan awal), final (vokal), dan nada. Contoh: \"mā\" (ibu), \"má\" (rami), \"mǎ\" (kuda), \"mà\" (memarahi) — empat kata berbeda hanya karena nadanya."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'HEADING', 4, $txt${"text": "Alat yang Dibutuhkan"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'LIST', 5, $txt${"items": ["Aplikasi kamus dengan audio pinyin (misalnya Pleco)", "Buku catatan untuk menulis pinyin dan nadanya", "Kartu nada: gambar 4 garis nada untuk dihafal", "Aplikasi perekam suara untuk membandingkan pengucapan"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'HEADING', 6, $txt${"text": "Langkah 1–3: Kuasai Empat Nada"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'PARAGRAPH', 7, $txt${"text": "Langkah 1: Pelajari tanda nada — nada 1 datar tinggi (ā), nada 2 naik (á), nada 3 turun-naik (ǎ), nada 4 turun tajam (à). Langkah 2: Latih dengan suku kata \"ma\" keempat-empatnya sampai telinga terbiasa. Langkah 3: Rekam suara sendiri dan bandingkan dengan audio asli."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'HEADING', 8, $txt${"text": "Langkah 4–6: Inisial dan Final"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'PARAGRAPH', 9, $txt${"text": "Langkah 4: Kuasai inisial yang sulit: zh, ch, sh, r (lidah digulung), serta j, q, x (lidah di depan). Langkah 5: Latih final seperti \"ü\" yang tidak ada di bahasa Indonesia. Langkah 6: Gabungkan — baca kata dua suku kata seperti \"nǐ hǎo\" (halo) dan \"xièxie\" (terima kasih) dengan nada benar."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'HEADING', 10, $txt${"text": "Risiko dan Kesalahan Umum"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'LIST', 11, $txt${"items": ["Mengabaikan nada: di Mandarin, nada mengubah arti kata sepenuhnya", "Membaca pinyin seperti bahasa Indonesia: \"c\" dibaca seperti \"ts\", \"x\" seperti \"sy\" lembut", "Terlalu cepat ke karakter: pinyin harus otomatis dulu sebelum belajar Hanzi"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'HEADING', 12, $txt${"text": "Penyelesaian: Target 30 Hari"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000001-5001-4501-8501-000000000001', 'LIST', 13, $txt${"items": ["Minggu 1: empat nada otomatis tanpa berpikir", "Minggu 2: semua inisial dan final bisa dibaca", "Minggu 3: membaca 50 kata sehari dengan nada benar", "Minggu 4: percakapan perkenalan dasar memakai pinyin"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'HEADING', 0, $txt${"text": "Masalah: Mata Perih Setelah Seharian Menatap Layar"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'PARAGRAPH', 1, $txt${"text": "Mata terasa kering, perih, buram sesaat, atau kepala pusing setelah berjam-jam menatap HP dan laptop — ini gejala umum kelelahan mata digital. Pekerja kantoran, pelajar, dan gamer paling sering mengalaminya. Kabar baiknya, sebagian besar kasus bisa diatasi dengan kebiasaan sederhana."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'HEADING', 2, $txt${"text": "Penjelasan: Mengapa Layar Melelahkan Mata?"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'PARAGRAPH', 3, $txt${"text": "Saat menatap layar, frekuensi kedipan turun dari sekitar 15–20 kali per menit menjadi 5–7 kali. Air mata menguap lebih cepat, permukaan mata mengering. Jarak pandang yang terlalu dekat dan cahaya layar yang terlalu terang memaksa otot fokus mata bekerja terus-menerus tanpa istirahat."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'HEADING', 4, $txt${"text": "Alat dan Persiapan"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'LIST', 5, $txt${"items": ["Timer atau aplikasi pengingat istirahat mata", "Tetes air mata buatan (bila perlu, sesuai anjuran apoteker)", "Pengaturan kecerahan dan mode malam di perangkat", "Jarak pandang ideal: layar sejauh lengan (50–70 cm)"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'HEADING', 6, $txt${"text": "Langkah 1–3: Aturan 20-20-20"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'PARAGRAPH', 7, $txt${"text": "Langkah 1: Setiap 20 menit, alihkan pandangan ke objek sejauh 20 kaki (6 meter) selama 20 detik. Langkah 2: Sambil istirahat, kedipkan mata dengan sadar 10–15 kali untuk membasahi permukaan mata. Langkah 3: Pasang timer agar tidak lupa — konsistensi adalah kuncinya."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'HEADING', 8, $txt${"text": "Langkah 4–6: Atur Lingkungan Layar"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'PARAGRAPH', 9, $txt${"text": "Langkah 4: Sesuaikan kecerahan layar dengan cahaya ruangan; jangan menatap layar terang di ruangan gelap. Langkah 5: Perbesar ukuran teks agar tidak menyipitkan mata. Langkah 6: Posisikan bagian atas layar sejajar atau sedikit di bawah garis pandang mata."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'HEADING', 10, $txt${"text": "Risiko: Jangan Abaikan Tanda Bahaya"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'LIST', 11, $txt${"items": ["Penglihatan ganda yang menetap atau kilatan cahaya: segera periksa ke dokter mata", "Nyeri mata hebat atau mata merah yang tidak membaik dalam 1–2 hari", "Mengandalkan tetes mata steroid tanpa resep dokter"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'HEADING', 12, $txt${"text": "Penyelesaian: Evaluasi Setelah 2 Minggu"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000002-5002-4502-8502-000000000002', 'LIST', 13, $txt${"items": ["Keluhan berkurang: lanjutkan kebiasaan 20-20-20 sebagai rutinitas", "Keluhan menetap: periksakan refraksi mata — mungkin butuh kacamata", "Artikel ini informasi umum, bukan pengganti nasihat medis; konsultasikan ke dokter bila ragu"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'HEADING', 0, $txt${"text": "Apa Itu Danau?"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'PARAGRAPH', 1, $txt${"text": "Danau adalah cekungan di daratan yang terisi air, dikelilingi daratan di semua sisi. Danau terbentuk lewat berbagai cara: aktivitas tektonik, letusan gunung berapi, gletser yang mencair, hingga bendungan sungai. Ukurannya bisa dari kolam kecil sampai seluas negara."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'HEADING', 2, $txt${"text": "Peringkat 1: Laut Kaspia"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'PARAGRAPH', 3, $txt${"text": "Laut Kaspia adalah danau terbesar di dunia dengan luas sekitar 371.000 km persegi — lebih luas dari Pulau Jawa. Meski bernama \"laut\", ia sepenuhnya dikelilingi daratan lima negara: Rusia, Kazakhstan, Turkmenistan, Iran, dan Azerbaijan. Airnya payau, dan ia adalah rumah bagi ikan sturgeon penghasil kaviar."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'HEADING', 4, $txt${"text": "Peringkat 2–3: Danau Superior dan Victoria"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'PARAGRAPH', 5, $txt${"text": "Danau Superior di perbatasan Amerika Serikat–Kanada adalah danau air tawar terbesar di dunia (82.100 km persegi), bagian dari Great Lakes. Danau Victoria di Afrika (68.800 km persegi) adalah danau terbesar kedua sekaligus danau tropis terbesar, dibagi tiga negara: Tanzania, Uganda, dan Kenya."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'HEADING', 6, $txt${"text": "Danau Terdalam dan Tertua: Baikal"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'PARAGRAPH', 7, $txt${"text": "Danau Baikal di Siberia adalah danau terdalam (1.642 meter) dan tertua di dunia (sekitar 25 juta tahun). Ia menyimpan sekitar seperlima cadangan air tawar permukaan dunia dan menjadi rumah bagi anjing laut Baikal, satu-satunya anjing laut air tawar di dunia."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'HEADING', 8, $txt${"text": "Kebanggaan Indonesia: Danau Toba"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'PARAGRAPH', 9, $txt${"text": "Danau Toba di Sumatera Utara adalah danau vulkanik terbesar di dunia (1.130 km persegi), terbentuk dari letusan supervulkan sekitar 74.000 tahun lalu — salah satu letusan terbesar dalam sejarah manusia. Di tengahnya ada Pulau Samosir, dan kawasan ini ditetapkan sebagai UNESCO Global Geopark."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'HEADING', 10, $txt${"text": "Fakta Menarik Lainnya"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'LIST', 11, $txt${"items": ["Laut Mati sebenarnya danau, dengan kadar garam 10 kali lipat air laut", "Danau Titicaca di Andes adalah danau tertinggi yang bisa dilayari kapal besar (3.812 mdpl)", "Danau Eyre di Australia kadang kering total lalu terisi kembali saat banjir besar", "Danau Chad di Afrika menyusut lebih dari 90 persen sejak 1960-an"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'HEADING', 12, $txt${"text": "Mengapa Danau Penting?"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000003-5003-4503-8503-000000000003', 'PARAGRAPH', 13, $txt${"text": "Danau menyimpan air tawar, mengatur iklim mikro, menjadi habitat ribuan spesies, dan menopang jutaan manusia lewat perikanan, pertanian, dan pariwisata. Menjaga kebersihan danau berarti menjaga sumber kehidupan — pencemaran limbah adalah ancaman terbesar bagi danau-danau dunia saat ini."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'HEADING', 0, $txt${"text": "Blockchain Bukan Sekadar Kripto"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'PARAGRAPH', 1, $txt${"text": "Kebanyakan orang mengenal blockchain lewat Bitcoin dan mata uang kripto. Padahal blockchain adalah teknologinya — fondasi di bawahnya — yang bisa dipakai untuk banyak hal lain. Memahami blockchain berarti memahami salah satu teknologi pencatatan paling inovatif abad ini."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'HEADING', 2, $txt${"text": "Definisi: Buku Besar Digital Bersama"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'PARAGRAPH', 3, $txt${"text": "Blockchain adalah buku besar (ledger) digital yang disalin ke ribuan komputer di seluruh dunia. Setiap \"blok\" berisi sekumpulan transaksi, dan setiap blok terhubung ke blok sebelumnya lewat kode kriptografi — membentuk \"rantai\" yang tidak bisa diubah sepihak."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'HEADING', 4, $txt${"text": "Cara Kerja: Tiga Pilar Utama"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'PARAGRAPH', 5, $txt${"text": "Pertama, desentralisasi: tidak ada satu server pusat; salinan data tersebar di banyak komputer (node). Kedua, kriptografi: setiap blok dikunci dengan hash yang bergantung pada blok sebelumnya, sehingga mengubah satu blok merusak seluruh rantai. Ketiga, konsensus: node-node menyepakati data yang valid lewat mekanisme seperti proof-of-work atau proof-of-stake."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'HEADING', 6, $txt${"text": "Mengapa Sulit Dipalsukan?"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'PARAGRAPH', 7, $txt${"text": "Untuk memalsukan satu catatan, penyerang harus mengubah blok tersebut dan semua blok setelahnya di mayoritas komputer jaringan secara bersamaan — secara praktis hampir mustahil pada jaringan besar seperti Bitcoin. Inilah yang membuat blockchain dipercaya tanpa perantara."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'HEADING', 8, $txt${"text": "Kegunaan di Luar Kripto"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'LIST', 9, $txt${"items": ["Rantai pasok: melacak asal kopi, ikan, atau obat dari produsen ke konsumen", "Sertifikat digital: ijazah dan dokumen yang tidak bisa dipalsukan", "Kontrak pintar (smart contract): perjanjian yang berjalan otomatis saat syarat terpenuhi", "Voting elektronik dan pencatatan tanah yang transparan"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'HEADING', 10, $txt${"text": "Keterbatasan yang Perlu Diketahui"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'LIST', 11, $txt${"items": ["Boros energi: beberapa jaringan memakai listrik setara negara kecil", "Lambat: transaksi per detik jauh di bawah sistem pembayaran konvensional", "Tidak bisa diubah: kesalahan pencatatan sulit dikoreksi", "Regulasi masih berkembang di banyak negara termasuk Indonesia"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'HEADING', 12, $txt${"text": "Kesimpulan"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000004-5004-4504-8504-000000000004', 'PARAGRAPH', 13, $txt${"text": "Blockchain adalah teknologi pencatatan terdistribusi yang aman dan transparan. Kripto hanyalah aplikasi pertamanya yang terkenal. Seperti internet di awal 1990-an, potensinya besar tetapi masih mencari bentuk terbaiknya — layak dipahami, tidak perlu ditakuti atau dipuja berlebihan."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, status, created_by, updated_by)
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'HEADING', 0, $txt${"text": "Tujuan Pembelajaran"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'LIST', 1, $txt${"items": ["Menjelaskan tujuan dan manfaat klasifikasi makhluk hidup", "Menyebutkan urutan tingkatan takson dari kingdom hingga spesies", "Mengidentifikasi ciri lima kingdom makhluk hidup", "Menggunakan kunci determinasi sederhana"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'HEADING', 2, $txt${"text": "Mengapa Makhluk Hidup Dikelompokkan?"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'PARAGRAPH', 3, $txt${"text": "Para ilmuwan memperkirakan ada 8,7 juta spesies di Bumi. Tanpa pengelompokan, mustahil mempelajarinya satu per satu. Klasifikasi mengelompokkan makhluk hidup berdasarkan persamaan ciri, sehingga mudah dipelajari, diberi nama ilmiah yang seragam, dan diketahui hubungan kekerabatannya."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'HEADING', 4, $txt${"text": "Tingkatan Takson"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'PARAGRAPH', 5, $txt${"text": "Urutan takson dari yang terbesar: Kingdom – Filum (hewan) atau Divisi (tumbuhan) – Kelas – Ordo – Famili – Genus – Spesies. Semakin ke bawah, persamaan cirinya semakin banyak. Contoh: manusia — Kingdom Animalia, Filum Chordata, Kelas Mammalia, Ordo Primata, Famili Hominidae, Genus Homo, Spesies Homo sapiens."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'HEADING', 6, $txt${"text": "Nama Ilmiah: Aturan Binomial Nomenklatur"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'PARAGRAPH', 7, $txt${"text": "Setiap spesies punya nama ilmiah dua kata: genus + spesies, ditulis miring atau bergaris bawah. Contoh: Oryza sativa (padi), Felis catus (kucing), Panthera tigris sumatrae (harimau sumatera). Aturan ini dibuat oleh Carolus Linnaeus pada 1753."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'HEADING', 8, $txt${"text": "Sistem Lima Kingdom"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'LIST', 9, $txt${"items": ["Monera: bersel satu tanpa membran inti (bakteri)", "Protista: bersel satu atau banyak, berinti sejati (amoeba, ganggang)", "Fungi/Jamur: pengurai, dinding sel dari kitin", "Plantae/Tumbuhan: berfotosintesis, dinding sel dari selulosa", "Animalia/Hewan: tidak berfotosintesis, bergerak aktif"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'HEADING', 10, $txt${"text": "Kunci Determinasi Sederhana"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'PARAGRAPH', 11, $txt${"text": "Kunci determinasi adalah panduan identifikasi berupa pilihan ciri yang berpasangan (dikotomi). Contoh: 1a. Bertulang belakang → lanjut ke 2; 1b. Tidak bertulang belakang → serangga. 2a. Berbulu dan menyusui → mamalia; 2b. Berbulu dan bertelur → burung. Dengan menjawab pilihan, kita tiba di nama kelompoknya."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'HEADING', 12, $txt${"text": "Latihan Soal"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'LIST', 13, $txt${"items": ["Sebutkan urutan tingkatan takson dari kingdom sampai spesies!", "Tuliskan nama ilmiah padi dan kucing sesuai aturan binomial nomenklatur!", "Sebutkan lima kingdom beserta satu contoh makhluk hidupnya!"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'HEADING', 14, $txt${"text": "Kunci Jawaban"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000005-5005-4505-8505-000000000005', 'LIST', 15, $txt${"items": ["Kingdom – Filum/Divisi – Kelas – Ordo – Famili – Genus – Spesies", "Oryza sativa dan Felis catus (genus kapital, spesies kecil, dicetak miring)", "Monera (bakteri), Protista (amoeba), Fungi (jamur merang), Plantae (mangga), Animalia (kucing)"]}$txt$) ON CONFLICT DO NOTHING;
