INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'LIST', 1, $txt${"items": ["Mengenal bentuk bangun datar: segitiga, segiempat, lingkaran", "Menyebutkan jumlah sisi dan sudut setiap bangun datar", "Mengelompokkan benda sehari-hari berdasarkan bentuknya"]}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'HEADING', 2, $txt${"text": "Apa Itu Bangun Datar?"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'PARAGRAPH', 3, $txt${"text": "Bangun datar adalah bentuk dua dimensi yang hanya punya panjang dan lebar, tidak punya tinggi atau tebal. Contohnya bisa kita lihat di sekitar: permukaan meja, layar HP, dan koin. Hari ini kita belajar tiga bangun datar: segitiga, segiempat, dan lingkaran."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'HEADING', 4, $txt${"text": "Segitiga: Tiga Sisi, Tiga Sudut"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'PARAGRAPH', 5, $txt${"text": "Segitiga punya 3 sisi dan 3 sudut. Lihat contohnya: potongan pizza, penggaris segitiga, dan rambu lalu lintas. Coba hitung dengan jarimu: satu, dua, tiga sisi — dan tiga sudut yang runcing."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'HEADING', 6, $txt${"text": "Segiempat: Empat Sisi, Empat Sudut"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'PARAGRAPH', 7, $txt${"text": "Segiempat punya 4 sisi dan 4 sudut. Contohnya: buku tulis, papan tulis, dan layar televisi. Ada segiempat khusus: persegi (semua sisi sama panjang) dan persegi panjang (sisi berhadapan sama panjang)."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'HEADING', 8, $txt${"text": "Lingkaran: Tanpa Sisi dan Sudut"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'PARAGRAPH', 9, $txt${"text": "Lingkaran tidak punya sisi dan tidak punya sudut — bentuknya melengkung penuh. Contohnya: koin, roda sepeda, dan jam dinding. Lingkaran istimewa karena setiap titik di garisnya berjarak sama dari tengah."}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'HEADING', 10, $txt${"text": "Ayo Mengelompokkan!"}$txt$) ON CONFLICT DO NOTHING;
INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'LIST', 11, $txt${"items": ["Benda berbentuk segitiga: penggaris segitiga, potongan semangka", "Benda berbentuk segiempat: buku, pintu, jendela", "Benda berbentuk lingkaran: piring, tutup botol, donat"]}$txt$) ON CONFLICT DO NOTHING;
