INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'LIST', 13, $txt${"items": ["Berapa jumlah sisi dan sudut segitiga?", "Sebutkan 3 benda di rumahmu yang berbentuk lingkaran!", "Apa perbedaan persegi dan persegi panjang?"]}$txt$) ON CONFLICT DO NOTHING;
