INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), 'e5000006-5006-4506-8506-000000000006', 'LIST', 15, $txt${"items": ["3 sisi dan 3 sudut", "Contoh: piring, jam dinding, koin, tutup panci", "Persegi semua sisinya sama panjang; persegi panjang hanya sisi yang berhadapan yang sama panjang"]}$txt$) ON CONFLICT DO NOTHING;
